package android.content;import java.io.*;import java.util.*;import android.net.Uri;public class ContentResolver {public boolean failOpen,failWrite,failPublish,failDelete;public int inserts,updates,deletes,streams;public volatile boolean mainIo;public final Map<Uri,byte[]> data=new HashMap<Uri,byte[]>();public final List<ContentValues> insertedValues=new ArrayList<ContentValues>(),updatedValues=new ArrayList<ContentValues>();public Uri last;public void check(){if(android.os.Looper.isMain())mainIo=true;}public Uri insert(Uri collection,ContentValues v){check();inserts++;insertedValues.add(new ContentValues());insertedValues.get(insertedValues.size()-1).putAll(v);last=Uri.parse(collection+"/"+inserts);data.put(last,new byte[0]);return last;}public OutputStream openOutputStream(final Uri u)throws IOException {return openOutputStream(u,"w");}public OutputStream openOutputStream(final Uri u,String mode)throws IOException {check();streams++;if(failOpen)throw new IOException("forced open");return new ByteArrayOutputStream(){public synchronized void write(byte[] b,int off,int n){if(failWrite)throw new RuntimeException("forced write");super.write(b,off,n);}public synchronized void write(int b){if(failWrite)throw new RuntimeException("forced write");super.write(b);}public void close()throws IOException{data.put(u,toByteArray());super.close();}};}public int update(Uri u,ContentValues v,String where,String[] args){check();updates++;ContentValues copy=new ContentValues();copy.putAll(v);updatedValues.add(copy);if(failPublish)return 0;return data.containsKey(u)?1:0;}public int delete(Uri u,String where,String[] args){check();deletes++;if(failDelete)throw new IllegalStateException("forced delete");data.remove(u);return 1;}}
